-- Per-user module settings (general, budgets, later accounts/transactions/...) stored as validated JSON,
-- an optional per-budget alert threshold, and a log of budget alerts for behaviour reports.
CREATE TABLE IF NOT EXISTS "UserModuleSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL,
    "Module" varchar(40) NOT NULL,
    "DataJson" text NOT NULL DEFAULT '{}',
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" timestamp with time zone NULL,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL,
    CONSTRAINT "FK_UserModuleSettings_Users_UserId" FOREIGN KEY ("UserId")
        REFERENCES identity."Users" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_UserModuleSettings_UserId_Module" ON "UserModuleSettings" ("UserId", "Module");

ALTER TABLE "Budgets" ADD COLUMN IF NOT EXISTS "AlertThresholdPercent" integer NULL;
ALTER TABLE "Budgets" DROP CONSTRAINT IF EXISTS "CK_Budget_AlertThreshold";
ALTER TABLE "Budgets" ADD CONSTRAINT "CK_Budget_AlertThreshold"
    CHECK ("AlertThresholdPercent" IS NULL OR ("AlertThresholdPercent" BETWEEN 50 AND 100));

CREATE TABLE IF NOT EXISTS "BudgetAlertEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL,
    "BudgetId" integer NOT NULL,
    "TransactionId" integer NULL,
    "Level" integer NOT NULL,                 -- 1 = threshold reached, 2 = limit reached
    "ThresholdPercent" integer NOT NULL,
    "PercentUsed" numeric(9,2) NOT NULL,
    "SpentAmount" numeric(18,2) NOT NULL,
    "BudgetAmount" numeric(18,2) NOT NULL,
    "CategoryName" varchar(200) NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" timestamp with time zone NULL,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL,
    CONSTRAINT "FK_BudgetAlertEvents_Users_UserId" FOREIGN KEY ("UserId")
        REFERENCES identity."Users" ("Id") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_BudgetAlertEvents_UserId_CreatedAt" ON "BudgetAlertEvents" ("UserId", "CreatedAt" DESC);
